parameters.jsCode:
const actividad = $('IA2 - Generación refuerzo').first().json.output;
const evaluacion = $('IA3 - Evaluación refuerzo').first().json.output;

const rag =
  $('Unificar contexto RAG refuerzo').first().json.contexto_rag ?? '';

const erroresIntento =
  $('Registrar intento').first().json.body?.errores ?? '';

const textoActividad = [
  actividad.titulo ?? '',
  actividad.enunciado ?? '',
  ...(actividad.conceptos_utilizados ?? [])
].join(' ').toLowerCase();

const textoRag = String(rag).toLowerCase();
const textoErrores = String(erroresIntento).toLowerCase();

const motivos = [];

// 1. Resultado de la evaluación mediante IA
if (evaluacion.valida !== true) {
  motivos.push('IA3 ha marcado la actividad de refuerzo como no válida.');
}

if (evaluacion.contenido_rag !== true) {
  motivos.push('IA3 indica que existe contenido no respaldado por el RAG.');
}

if (evaluacion.error_reforzado !== true) {
  motivos.push('La actividad no trabaja correctamente el error registrado.');
}

if (evaluacion.objetivo_correcto !== true) {
  motivos.push('La actividad no mantiene correctamente el objetivo de refuerzo.');
}

if (evaluacion.personalizacion_correcta !== true) {
  motivos.push('La personalización no corresponde correctamente con el perfil.');
}

// 2. Violaciones detectadas por IA3
const violacionesRag = Array.isArray(evaluacion.violaciones_rag)
  ? evaluacion.violaciones_rag
  : [];

if (violacionesRag.length > 0) {
  motivos.push(
    `IA3 ha detectado violaciones RAG: ${violacionesRag.join(' | ')}`
  );
}

// 3. Debe existir al menos un error trabajado
const erroresTrabajados = Array.isArray(actividad.errores_trabajados)
  ? actividad.errores_trabajados
  : [];

if (erroresTrabajados.length === 0) {
  motivos.push('La actividad de refuerzo no identifica ningún error trabajado.');
}

// 4. Detectar ejemplos numéricos de range() que no existan en el RAG
function extraerRangeNumericos(texto) {
  return [
    ...String(texto).matchAll(/range\s*\(\s*(\d+)\s*\)/gi)
  ].map(match => Number(match[1]));
}

const ejemplosPermitidos = new Set(extraerRangeNumericos(textoRag));
const ejemplosActividad = [...new Set(extraerRangeNumericos(textoActividad))];

const ejemplosNoPermitidos = ejemplosActividad.filter(
  numero => !ejemplosPermitidos.has(numero)
);

if (ejemplosNoPermitidos.length > 0) {
  motivos.push(
    `La actividad introduce ejemplos de range() no presentes explícitamente en el RAG: ${ejemplosNoPermitidos
      .map(numero => `range(${numero})`)
      .join(', ')}.`
  );
}

// 5. Evitar generalizaciones de range(n) si no aparecen en el material
if (
  textoActividad.includes('range(n)') &&
  !textoRag.includes('range(n)')
) {
  motivos.push(
    'La actividad generaliza el contenido a range(n), aunque esa regla no aparece en el RAG.'
  );
}

// 6. Conceptos problemáticos no respaldados
const expresionesControladas = [
  'off-by-one',
  'límite superior',
  'valor superior',
  'errores comunes'
];

for (const expresion of expresionesControladas) {
  if (
    textoActividad.includes(expresion) &&
    !textoRag.includes(expresion) &&
    !textoErrores.includes(expresion)
  ) {
    motivos.push(
      `La actividad introduce "${expresion}", que no aparece en el RAG ni en los errores reales del intento.`
    );
  }
}

const validaFinal = motivos.length === 0;

return {
  json: {
    actividad,
    evaluacion_ia: evaluacion,
    guardrail_determinista: {
      valido: validaFinal,
      motivos
    },
    valida_final: validaFinal
  }
};

const items = $input.all();

const documentos = items
  .map((item) => ({
    contenido: item.json.document?.pageContent ?? '',
    metadata: item.json.document?.metadata ?? {},
    score: item.json.score ?? null,
  }))
  .filter((doc) => doc.contenido);

const contextoRag = documentos
  .map(
    (doc, index) =>
      `FRAGMENTO ${index + 1}:\n${doc.contenido}`
  )
  .join('\n\n');

return [
  {
    json: {
      contexto_rag: contextoRag,
      referencias_rag: documentos.map((doc) => ({
        metadata: doc.metadata,
        score: doc.score,
      })),
    },
  },
];
